DROP TABLE IF EXISTS `shared_model_offset_credit`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shared_model_offset_credit` (
  `id` int NOT NULL AUTO_INCREMENT,
  `approved_minutes` int unsigned NOT NULL,
  `used_minutes` int unsigned NOT NULL,
  `remaining_minutes` int unsigned NOT NULL,
  `target_date` date NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `approved_at` datetime(6) DEFAULT NULL,
  `consumed_at` datetime(6) DEFAULT NULL,
  `expired_at` datetime(6) DEFAULT NULL,
  `remarks` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `approved_by_id` int DEFAULT NULL,
  `attendance_id` int NOT NULL,
  `employee_id` int NOT NULL,
  `source_request_id` int NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `source_request_id` (`source_request_id`),
  KEY `shared_mode_employe_ebd498_idx` (`employee_id`,`target_date`,`status`),
  KEY `shared_model_offset__approved_by_id_f33e3324_fk_users_use` (`approved_by_id`),
  KEY `shared_model_offset__attendance_id_49ee35f7_fk_shared_mo` (`attendance_id`),
  CONSTRAINT `shared_model_offset__approved_by_id_f33e3324_fk_users_use` FOREIGN KEY (`approved_by_id`) REFERENCES `users` (`user_id`),
  CONSTRAINT `shared_model_offset__attendance_id_49ee35f7_fk_shared_mo` FOREIGN KEY (`attendance_id`) REFERENCES `shared_model_attendance` (`id`),
  CONSTRAINT `shared_model_offset__employee_id_396ffcaf_fk_shared_mo` FOREIGN KEY (`employee_id`) REFERENCES `shared_model_employee` (`id`),
  CONSTRAINT `shared_model_offset__source_request_id_83404715_fk_shared_mo` FOREIGN KEY (`source_request_id`) REFERENCES `shared_model_excess_time_request` (`id`),
  CONSTRAINT `shared_model_offset_credit_chk_1` CHECK ((`approved_minutes` >= 0)),
  CONSTRAINT `shared_model_offset_credit_chk_2` CHECK ((`used_minutes` >= 0)),
  CONSTRAINT `shared_model_offset_credit_chk_3` CHECK ((`remaining_minutes` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
